#include <stdio.h>
#include <stdlib.h>

/* 两数之和判定问题: 给定 n 个整数与目标值 t, 判定是否存在两数之和等于 t
   属于 P 类: 排序 O(n log n) + 双指针 O(n), 输出 YES/NO */
int cmp_int(const void *a, const void *b) {
    return *(const int *)a - *(const int *)b;
}

int main(void) {
    int n, t, a[100];
    printf("输入整数个数 n 与目标值 t (n<=100): ");
    if (scanf("%d %d", &n, &t) != 2 || n < 2 || n > 100) {
        printf("输入无效!\n");
        return 1;
    }
    printf("输入 %d 个整数: ", n);
    for (int i = 0; i < n; i++) scanf("%d", &a[i]);

    qsort(a, n, sizeof(int), cmp_int);      /* 排序: O(n log n) */
    int lo = 0, hi = n - 1, found = 0;
    while (lo < hi) {                        /* 双指针: O(n) */
        int s = a[lo] + a[hi];
        if (s == t) {
            found = 1;
            printf("YES: %d + %d = %d\n", a[lo], a[hi], t);
            break;
        }
        if (s < t) lo++; else hi--;
    }
    if (found) printf("判定结果: YES\n");
    else printf("判定结果: NO\n");
    return 0;
}

#include <stdio.h>
#include <stdbool.h>

/* CNF-SAT 验证器: 输入合取范式公式与一组赋值, 多项式时间验证该赋值是否满足公式
   验证器是 NP 定义的载体: 赋值就是「证书」(certificate), 验证只需 O(总文字数) */
#define MAXV 30    /* 变量数上限 */
#define MAXC 30    /* 子句数上限 */
#define MAXL 10    /* 单个子句文字数上限 */

int main(void) {
    int n, m, len[MAXC], lit[MAXC][MAXL], val[MAXV + 1];
    printf("输入变量数 n 与子句数 m (n,m <= 30): ");
    if (scanf("%d %d", &n, &m) != 2 || n < 1 || n > MAXV || m < 1 || m > MAXC) {
        printf("输入无效!\n");
        return 1;
    }
    printf("逐行输入子句: 先给文字个数 k, 再给 k 个文字(正数 x 表示变量 x 取真, 负数 -x 表示取假)\n");
    for (int i = 0; i < m; i++) {
        scanf("%d", &len[i]);
        if (len[i] < 1 || len[i] > MAXL) { printf("子句长度无效!\n"); return 1; }
        for (int j = 0; j < len[i]; j++) scanf("%d", &lit[i][j]);
    }
    printf("输入赋值(变量 1..%d 各取 0 或 1, 共 %d 个数): ", n, n);
    for (int i = 1; i <= n; i++) scanf("%d", &val[i]);

    int total = 0;
    for (int i = 0; i < m; i++) {           /* 逐子句检查, 总代价 O(总文字数) */
        bool ok = false;
        total += len[i];
        for (int j = 0; j < len[i]; j++) {
            int l = lit[i][j];
            bool v = (l > 0) ? (val[l] == 1) : (val[-l] == 0);
            if (v) { ok = true; break; }
        }
        if (!ok) {
            printf("不满足: 第 %d 个子句全部文字为假\n", i + 1);
            return 0;
        }
    }
    printf("满足! 该赋值使公式为真 (共检查 %d 次文字)\n", total);
    return 0;
}

#include <stdio.h>
#include <stdbool.h>

/* 多项式时间归约演示: SAT ≤p 3-SAT
   每个子句按长度处理: k=1,2 用新变量补足; k=3 原样保留; k>=4 用链式 gadget 拆分
   归约保持可满足性: 原公式可满足 ⟺ 构造的 3-CNF 可满足 (末尾暴力枚举验证, 仅限极小规模) */
#define MAXV 8
#define MAXC 5
#define MAXL 8
#define MAXOUT 100

int main(void) {
    int n, m, len[MAXC], lit[MAXC][MAXL];
    printf("输入变量数 n 与子句数 m (演示用小规模: n<=8, m<=5): ");
    if (scanf("%d %d", &n, &m) != 2 || n < 1 || n > MAXV || m < 1 || m > MAXC) {
        printf("输入无效!\n");
        return 1;
    }
    printf("逐行输入子句: 先给文字个数 k, 再给 k 个文字(正=变量取真, 负=变量取假)\n");
    for (int i = 0; i < m; i++) {
        scanf("%d", &len[i]);
        if (len[i] < 1 || len[i] > MAXL) { printf("子句长度无效!\n"); return 1; }
        for (int j = 0; j < len[i]; j++) scanf("%d", &lit[i][j]);
    }

    int n2 = n, out[MAXOUT][3], cnt = 0;   /* 构造 3-CNF: 新变量从 n+1 开始编号 */
    for (int i = 0; i < m; i++) {
        int k = len[i];
        if (k == 1) {                      /* (l) 拆为四个三文字子句, 强制 l 为真 */
            int y = ++n2, z = ++n2;
            out[cnt][0] = lit[i][0]; out[cnt][1] = y; out[cnt][2] = z; cnt++;
            out[cnt][0] = lit[i][0]; out[cnt][1] = -y; out[cnt][2] = z; cnt++;
            out[cnt][0] = lit[i][0]; out[cnt][1] = y; out[cnt][2] = -z; cnt++;
            out[cnt][0] = lit[i][0]; out[cnt][1] = -y; out[cnt][2] = -z; cnt++;
        } else if (k == 2) {               /* (l1∨l2) 拆为 (l1∨l2∨y)(l1∨l2∨¬y) */
            int y = ++n2;
            out[cnt][0] = lit[i][0]; out[cnt][1] = lit[i][1]; out[cnt][2] = y; cnt++;
            out[cnt][0] = lit[i][0]; out[cnt][1] = lit[i][1]; out[cnt][2] = -y; cnt++;
        } else if (k == 3) {
            out[cnt][0] = lit[i][0]; out[cnt][1] = lit[i][1]; out[cnt][2] = lit[i][2]; cnt++;
        } else {                           /* k>=4: 链式拆分, 引入 k-3 个新变量 */
            int y[MAXL];
            for (int t = 0; t < k - 3; t++) y[t] = ++n2;
            out[cnt][0] = lit[i][0]; out[cnt][1] = lit[i][1]; out[cnt][2] = y[0]; cnt++;
            for (int t = 1; t < k - 3; t++) {
                out[cnt][0] = -y[t - 1]; out[cnt][1] = lit[i][t + 1]; out[cnt][2] = y[t]; cnt++;
            }
            out[cnt][0] = -y[k - 4]; out[cnt][1] = lit[i][k - 2]; out[cnt][2] = lit[i][k - 1]; cnt++;
        }
    }

    printf("构造的 3-CNF (变量 1..%d, 共 %d 个子句):\n", n2, cnt);
    for (int i = 0; i < cnt; i++)
        printf("(%s%d ∨ %s%d ∨ %s%d)\n",
               out[i][0] < 0 ? "¬" : "", out[i][0] < 0 ? -out[i][0] : out[i][0],
               out[i][1] < 0 ? "¬" : "", out[i][1] < 0 ? -out[i][1] : out[i][1],
               out[i][2] < 0 ? "¬" : "", out[i][2] < 0 ? -out[i][2] : out[i][2]);

    /* 暴力枚举验证等可满足性 (2^n2 种赋值, 仅当 n2 <= 20 时执行) */
    if (n2 > 20) {
        printf("变量过多, 跳过暴力等价验证。\n");
        return 0;
    }
    bool sat1 = false, sat2 = false;
    for (int mask = 0; mask < (1 << n2); mask++) {
        bool ok1 = true, ok2 = true;
        for (int i = 0; i < m && ok1; i++) {         /* 原公式只用前 n 个变量 */
            bool c = false;
            for (int j = 0; j < len[i]; j++) {
                int l = lit[i][j];
                bool v = (l > 0) ? ((mask >> (l - 1)) & 1) : !((mask >> (-l - 1)) & 1);
                if (v) { c = true; break; }
            }
            if (!c) ok1 = false;
        }
        for (int i = 0; i < cnt && ok2; i++) {       /* 3-CNF */
            bool c = false;
            for (int j = 0; j < 3; j++) {
                int l = out[i][j];
                bool v = (l > 0) ? ((mask >> (l - 1)) & 1) : !((mask >> (-l - 1)) & 1);
                if (v) { c = true; break; }
            }
            if (!c) ok2 = false;
        }
        if (ok1) sat1 = true;
        if (ok2) sat2 = true;
    }
    printf("原公式可满足: %s\n", sat1 ? "是" : "否");
    printf("3-CNF 可满足: %s\n", sat2 ? "是" : "否");
    printf("两者一致 => 归约保持可满足性 (等可满足性) ✓\n");
    return 0;
}

