#include <stdio.h>

/* 子集和问题: 给定正整数集合与目标值 S, 判定是否存在子集和恰为 S
   回溯搜索: 最坏情形 O(2^n) —— NPC 问题没有已知多项式算法
   剪枝: sum > S, 以及剩余元素全选也达不到 S (后缀和) */
#define MAXN 40

int a[MAXN], n, S, sol[MAXN], cnt = 0, found = 0;
int suffix[MAXN + 1];                /* suffix[i] = a[i..n-1] 的和 */

void dfs(int i, int sum) {
    if (found) return;
    if (sum == S) { found = 1; return; }        /* 找到一组解 */
    if (i >= n || sum > S) return;
    if (sum + suffix[i] < S) return;            /* 剪枝: 剩余全选也不够 */
    sol[cnt++] = a[i];                          /* 分支 1: 选 a[i] */
    dfs(i + 1, sum + a[i]);
    if (found) return;
    cnt--;                                      /* 回溯 */
    dfs(i + 1, sum);                            /* 分支 2: 不选 a[i] */
}

int main(void) {
    printf("输入元素个数 n 与目标值 S (n<=%d): ", MAXN);
    if (scanf("%d %d", &n, &S) != 2 || n < 1 || n > MAXN || S < 0) {
        printf("输入无效!\n");
        return 1;
    }
    printf("输入 %d 个正整数: ", n);
    for (int i = 0; i < n; i++) scanf("%d", &a[i]);
    suffix[n] = 0;
    for (int i = n - 1; i >= 0; i--) suffix[i] = suffix[i + 1] + a[i];

    dfs(0, 0);
    if (found) {
        printf("YES: 存在子集 {");
        for (int i = 0; i < cnt; i++) printf("%d%s", sol[i], i + 1 < cnt ? ", " : "");
        printf("} 和为 %d\n", S);
    } else {
        printf("NO: 不存在和为 %d 的子集\n", S);
    }
    return 0;
}

sections.theory:
## NP 难与 NPC 的区别

语言 H 是 **NP 难(NP-hard)** 的, 若所有 NP 问题都可多项式归约到它; **NPC = NP 难 ∩ NP**。差别只在「是否属于 NP」。最生动的例子是**停机问题**: 对任意可判定语言 L, 构造程序 M~x~(无视输入, 若 x ∈ L 则停机, 否则死循环), 则 x ∈ L ⟺ M~x~ 停机——所以一切 NP 问题(乃至一切可判定问题)都能归约到停机问题, 停机问题是 NP 难的; 但它不可判定, 根本不在 NP 中。

## 不可判定性与对角线论证

**停机问题**: 给定程序 P 与输入 x, P 在 x 上是否停机? 图灵 1936 年证明不可判定。**对角线论证**: 假设存在判定停机的程序 H(P, x); 构造程序 D(x): 若 H(x, x) 说「停机」则死循环, 否则停机。问 D 在输入 D 上是否停机: 若停机, 则 H(D, D) 说「停机」, 而 D 的定义使它死循环——矛盾; 若不停机, 同理矛盾。这说明「可判定」本身存在不可逾越的边界, 与算法好坏无关。

## 处理 NPC 问题的实际策略

- **近似算法**: 最坏情形下有保证的次优解, 用**近似比**度量: 最小化问题取 ρ = A(I) / OPT(I) 在所有实例上的最大值; 最大化问题取 ρ = OPT(I) / A(I)。例如顶点覆盖有 2-近似(最大匹配法, 见本章代码), 欧氏 TSP 有 1.5-近似;
- **启发式**: 模拟退火、遗传算法、局部搜索——工程上常用, 但无最坏情形保证;
- **参数化算法**: 复杂度 O(f(k)·n^c), 指数只压在参数 k 上, k 小时实用, 如顶点覆盖的 O(2^k·n) 分支算法(见练习);
- **分支限界**: 精确求解 + 剪枝, 最坏仍指数, 但可解中等规模实例;
- 此外还有随机化算法、实例专用技巧与多种策略的混合。

## 易错点

NP 难 ≠ 不可判定(NP 难问题可以可判定, 如 TSP; 不可判定问题如停机问题甚至不在 NP 中); 近似比是**最坏情形**比值, 不是平均表现; 有近似算法 ≠ 问题变容易——一般 TSP 连常数近似都没有(除非 P = NP)。

