#include <stdio.h>
#include <stdbool.h>

/* 顶点覆盖 2-近似: 最大匹配法 (贪心)
   每次取一条两端都未被覆盖的边 (u,v), 把 u,v 都加入覆盖
   选中的边构成匹配 M: 每条匹配边至少要一个端点属于任何覆盖, 故 OPT >= |M|
   算法输出 = 2|M| <= 2*OPT => 近似比 <= 2 */
#define MAXN 100
#define MAXM 500

int main(void) {
    int n, m, U[MAXM], V[MAXM];
    printf("输入顶点数 n 与边数 m (n<=%d, m<=%d): ", MAXN, MAXM);
    if (scanf("%d %d", &n, &m) != 2 || n < 1 || n > MAXN || m < 0 || m > MAXM) {
        printf("输入无效!\n");
        return 1;
    }
    printf("逐行输入边 (顶点编号 1..n):\n");
    for (int i = 0; i < m; i++) scanf("%d %d", &U[i], &V[i]);

    bool in_cover[MAXN + 1] = { false };
    int matching = 0;
    for (int i = 0; i < m; i++) {
        if (!in_cover[U[i]] && !in_cover[V[i]]) {   /* 两端都未覆盖 -> 加入匹配 */
            in_cover[U[i]] = in_cover[V[i]] = true;
            matching++;
        }
    }

    int size = 0;
    printf("覆盖顶点集合: ");
    for (int v = 1; v <= n; v++)
        if (in_cover[v]) { printf("%d ", v); size++; }
    printf("\n覆盖大小 = %d, 匹配边数 = %d\n", size, matching);
    printf("近似比保证: 2*|M| / OPT <= 2 (因为 OPT >= |M|)\n");
    return 0;
}
